// sketch.ino — ESP32-S3 (нативный USB, режим USB-OTG)
// Полностью автономный сценарий:
//   1. Гарантирует NumLock (читает реальное состояние через LED-отчёт от ОС)
//   2. Всё печатает Alt-кодами — раскладка системы вообще не важна
//   3. Создаёт %USERPROFILE%\script.bat и запускает его в этом же окне
//   4. Разворачивает окно на весь экран (F11)

#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

// ---------- Состояние LED, получаемое от ОС ----------
volatile bool    ledKnown = false;   // получали ли мы хоть один LED-отчёт
volatile uint8_t ledByte  = 0;       // биты: LED_NUMLOCK | LED_CAPSLOCK | LED_SCROLL_LOCK

// Колбэк на события от клавиатурного интерфейса
void keyboardEventCallback(void* arg, esp_event_base_t base, int32_t id, void* data) {
  if (id == ARDUINO_USB_HID_KEYBOARD_LED_EVENT) {
    arduino_usb_hid_keyboard_event_data_t* led = (arduino_usb_hid_keyboard_event_data_t*)data;
    ledByte  = led->leds;
    ledKnown = true;
  }
}

// Гарантия NumLock: ждём LED-отчёт от хоста, включаем только если реально выключен.
// Если отчёт так и не пришёл (старое/сломанное ядро) — по флагу ниже можно
// включить "слепое" нажатие NumLock, но это лотерея: может выключить включённый.
#define BLIND_NUMLOCK_FALLBACK 0

void ensureNumLock() {
  for (int i = 0; i < 30 && !ledKnown; i++) {   // ждём до 3 секунд
    delay(100);
  }
  if (ledKnown) {
    if (!(ledByte & LED_NUMLOCK)) {
      Keyboard.press(KEY_NUM_LOCK);
      delay(60);
      Keyboard.release(KEY_NUM_LOCK);
      delay(300);
    }
  } else {
#if BLIND_NUMLOCK_FALLBACK
    Keyboard.press(KEY_NUM_LOCK);
    delay(60);
    Keyboard.release(KEY_NUM_LOCK);
    delay(300);
#endif
  }
}

// ---------- Ввод через Alt-коды (не зависит от раскладки) ----------
const uint8_t NUMPAD[10] = {
  KEY_KP_0, KEY_KP_1, KEY_KP_2, KEY_KP_3, KEY_KP_4,
  KEY_KP_5, KEY_KP_6, KEY_KP_7, KEY_KP_8, KEY_KP_9
};

void altChar(unsigned char c) {
  Keyboard.press(KEY_LEFT_ALT);
  delay(40);

  unsigned int code = c;
  unsigned int div = 1;
  while (code / div >= 10) div *= 10;
  while (div) {
    uint8_t d = (code / div) % 10;
    Keyboard.press(NUMPAD[d]);
    delay(25);
    Keyboard.release(NUMPAD[d]);
    delay(25);
    div /= 10;
  }

  Keyboard.release(KEY_LEFT_ALT);
  delay(80);
}

void typeText(const char* s) {
  while (*s) altChar(*s++);
}

void pressEnter() {
  Keyboard.press(KEY_RETURN);
  delay(50);
  Keyboard.releaseAll();
}

// ---------- Сценарий ----------
const char* BAT_PATH = "%USERPROFILE%\\script.bat";

void setup() {
  Keyboard.onEvent(keyboardEventCallback);  // подписка на LED-события
  Keyboard.begin();
  USB.begin();

  delay(5000);      // ждём, пока ОС распознает HID-клавиатуру
  ensureNumLock();  // NumLock теперь самообслуживается

  // Win + R -> cmd
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(100);
  Keyboard.releaseAll();
  delay(1000);

  typeText("cmd");
  pressEnter();
  delay(2500);

  // --- Создаём script.bat построчно ---
  typeText("echo @echo off>");
  typeText(BAT_PATH);
  pressEnter(); delay(200);

  typeText("echo color 2 >>");   // пробел перед >> обязателен
  typeText(BAT_PATH);
  pressEnter(); delay(200);

  typeText("echo :x>>");
  typeText(BAT_PATH);
  pressEnter(); delay(200);

  typeText("echo dir/s>>");
  typeText(BAT_PATH);
  pressEnter(); delay(200);

  typeText("echo goto x>>");
  typeText(BAT_PATH);
  pressEnter(); delay(400);

  // --- Запускаем батник прямо в этом окне: бесконечный dir/s
  //     пойдёт здесь же, и F11 развернёт именно это окно ---
  typeText(BAT_PATH);
  pressEnter();

  delay(2000);
  Keyboard.press(KEY_F11);
  delay(100);
  Keyboard.releaseAll();
  // Всё. Окно полноэкранное, зелёный dir /s крутится вечно.
}

void loop() {}
